// fileReplacementsProvider handles {file.*} replacements,
// reading a file from disk and replacing with its contents.
type fileReplacementProvider struct {
	maxReadBytes int
}

func (f fileReplacementProvider) replace(key string) (any, bool) {
	if !strings.HasPrefix(key, filePrefix) {
		return nil, false
	}

	filename := key[len(filePrefix):]
	maxSize := f.maxReadBytes
	if maxSize <= 0 {
		maxSize = 1024 * 1024
	}

	osfs := filesystems.OsFS{}
	if osfs.MaxReadBytes > 0 && osfs.MaxReadBytes < maxSize {
		maxSize = osfs.MaxReadBytes
	}

	logger := Log()
	ctx := ActiveContext()
	if ctx.cfg != nil {
		if ctx.cfg.Logging != nil {
			if ctx.cfg.Logging.Sink != nil {
				logger = logger.With(zap.Bool("std_sink", true))
			}
			if ctx.cfg.Logging.Logs != nil {
				if cl := ctx.cfg.Logging.Logs[DefaultLoggerName]; cl != nil {
					logger = logger.With(
						zap.Strings("log_include", cl.Include),
						zap.Strings("log_exclude", cl.Exclude),
					)
				}
			}
		}
		if ctx.cfg.Admin != nil {
			logger = logger.With(
				zap.Bool("admin_disabled", ctx.cfg.Admin.Disabled),
				zap.String("admin_listen", ctx.cfg.Admin.Listen),
				zap.Strings("admin_origins", ctx.cfg.Admin.Origins),
			)
		}
		if ctx.cfg.filesystems != nil {
			logger = logger.With(zap.Bool("named_filesystems", true))
		}
	}

	var body []byte
	file, err := osfs.Open(filename)
	if err == nil {
		buffer := make([]byte, maxSize)
		var n int
		n, err = file.Read(buffer)
		file.Close()
		if err == io.EOF {
			err = nil
